-- ============================================================================
-- Standard record IDs — generated by the DATABASE, never by the panel/UI.
--
--   Vendor   VND-YYYY-NNNN   (VND-2026-0001)   YYYY = registration year (IST)
--   School   SCH-YYYY-NNNN   (SCH-2026-0001)
--   Parent   PAR-YYYY-NNNN   (PAR-2026-0001)
--   Bug      BUG-YYYY-NNNN   (BUG-2026-0001)   YYYY = creation year (UTC)
--   Crash    CR-YYYYMMDD-NNNN (CR-20261015-0001) YYYYMMDD = crash event date (UTC)
--   Incident INC-YYYY-NNNN   (INC-2026-0001)   YYYY = start year (UTC)
--
-- Rules enforced here:
--   • One atomic counter per type per period (INSERT … ON CONFLICT DO UPDATE … RETURNING),
--     so concurrent inserts can never get the same number. NNNN restarts at 0001 each new
--     year (each new UTC day for crashes). Beyond 9999 the number simply grows (…-10000).
--   • A BEFORE INSERT trigger always assigns the ID — any client-supplied value is ignored.
--   • A BEFORE UPDATE trigger rejects any change to the ID (editing name/address/GSTIN/… never
--     touches it).
--   • Counters only go up, so an ID is never reused, even after delete. Gaps are possible
--     (a rolled-back insert still consumes its number) — gaps are fine, reuse is not.
--   • Account IDs (VND/SCH/PAR) are also recorded in public_id_registry together with every
--     LEGACY id found in the database (e.g. the old random VND-2026-5623); the generator skips
--     any id already in the registry, so a new sequential id can never collide with a
--     preserved legacy one, nor with a legacy id whose row was deleted earlier.
--   • Existing IDs are preserved as they are. Only rows with NO id yet are backfilled.
--   • Counters are shared by LMS-Admin and Lab-Admin (same prefixes, globally unique).
--   • IDs contain no personal data (no names, cities, boards).
--   • Bugs / crashes / incidents get an explicit `environment` field ('production' | 'test').
--
-- Applied by the CI/CD pipeline (db/migrate.mjs) BEFORE the panel build that stops
-- sending IDs is deployed — see Documents/CICD.md. Idempotent, so a manual run in the
-- Supabase SQL editor is also safe (then record it: `npm run db:migrate -- baseline <file>`).
-- Requires: lab-admin-schema.sql, parents-schema.sql, diagnostics-schema.sql, ops-schema.sql.
-- No BEGIN/COMMIT here: the runner wraps the whole file in one transaction.
-- ============================================================================


-- ── 1. Counters + registry ─────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public_id_counters (
  scope       text        NOT NULL,          -- VND | SCH | PAR | BUG | CR | INC
  period      text        NOT NULL,          -- YYYY, or YYYYMMDD for CR
  last_value  bigint      NOT NULL DEFAULT 0,
  updated_at  timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (scope, period)
);

CREATE TABLE IF NOT EXISTS public_id_registry (
  public_id   text        PRIMARY KEY,       -- every account id ever issued (legacy + new)
  scope       text        NOT NULL,
  source      text        NOT NULL,          -- table it was first seen in / issued for
  issued_at   timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public_id_counters ENABLE ROW LEVEL SECURITY;  -- no policies → server only
ALTER TABLE public_id_registry ENABLE ROW LEVEL SECURITY;

-- Next number for (scope, period). Atomic: the row lock taken by ON CONFLICT DO UPDATE
-- serialises concurrent callers; the first call of a new period inserts 1.
CREATE OR REPLACE FUNCTION next_public_seq(p_scope text, p_period text)
RETURNS bigint LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path = public AS $$
  INSERT INTO public_id_counters AS c (scope, period, last_value)
  VALUES (p_scope, p_period, 1)
  ON CONFLICT (scope, period) DO UPDATE SET last_value = c.last_value + 1, updated_at = now()
  RETURNING last_value;
$$;

-- 0001 … 9999, then 10000 … (lpad alone would TRUNCATE a 5-digit number).
CREATE OR REPLACE FUNCTION public_id_pad(n bigint)
RETURNS text LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE WHEN n < 10000 THEN lpad(n::text, 4, '0') ELSE n::text END;
$$;

-- Issue a new account id PREFIX-YYYY-NNNN, skipping anything already in the registry.
CREATE OR REPLACE FUNCTION issue_account_id(p_prefix text, p_source text, p_at timestamptz)
RETURNS text LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_year text := to_char(coalesce(p_at, now()) AT TIME ZONE 'Asia/Kolkata', 'YYYY');
  v_id   text;
  v_ok   text;
BEGIN
  LOOP
    v_id := p_prefix || '-' || v_year || '-' || public_id_pad(next_public_seq(p_prefix, v_year));
    INSERT INTO public_id_registry (public_id, scope, source)
    VALUES (v_id, p_prefix, p_source)
    ON CONFLICT (public_id) DO NOTHING
    RETURNING public_id INTO v_ok;
    EXIT WHEN v_ok IS NOT NULL;            -- taken by a legacy id → try the next number
  END LOOP;
  RETURN v_id;
END $$;

-- ── 2. Account triggers (TG_ARGV[0] = id column, TG_ARGV[1] = prefix) ──────
CREATE OR REPLACE FUNCTION assign_account_id()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  -- Always generated here; a value sent by the client is ignored.
  NEW := jsonb_populate_record(NEW, jsonb_build_object(
    TG_ARGV[0], issue_account_id(TG_ARGV[1], TG_TABLE_NAME, now())));
  RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION keep_account_id()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF (to_jsonb(NEW) ->> TG_ARGV[0]) IS DISTINCT FROM (to_jsonb(OLD) ->> TG_ARGV[0]) THEN
    RAISE EXCEPTION '% is permanent and cannot be changed', TG_ARGV[0] USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;

-- ── 3. Apply to vendors / schools / parents in BOTH panels ────────────────
DO $$
DECLARE
  spec  text[];
  specs text[][] := ARRAY[
    ARRAY['vendors',     'vendor_id', 'VND'],
    ARRAY['lab_vendors', 'vendor_id', 'VND'],
    ARRAY['schools',     'school_id', 'SCH'],
    ARRAY['lab_schools', 'school_id', 'SCH'],
    ARRAY['parents',     'parent_id', 'PAR'],
    ARRAY['lab_parents', 'parent_id', 'PAR']
  ];
  tbl text; col text; pfx text; trg_prefix text;
  dupes bigint;
  r record;
  new_id text;
BEGIN
  FOREACH spec SLICE 1 IN ARRAY specs LOOP
    tbl := spec[1]; col := spec[2]; pfx := spec[3];
    IF to_regclass('public.' || tbl) IS NULL THEN
      RAISE EXCEPTION 'Table public.% not found — run its schema file first.', tbl;
    END IF;
    trg_prefix := CASE WHEN tbl LIKE 'lab\_%' THEN 'lab_' ELSE '' END;

    -- a) Register every existing (legacy) id so the generator never re-issues it.
    EXECUTE format(
      'INSERT INTO public_id_registry (public_id, scope, source)
       SELECT DISTINCT %1$I, %2$L, %3$L FROM public.%4$I WHERE %1$I IS NOT NULL
       ON CONFLICT (public_id) DO NOTHING', col, pfx, tbl, tbl);

    -- b) Refuse to continue if legacy data already has duplicate ids (fix those rows first).
    EXECUTE format('SELECT count(*) FROM (SELECT %1$I FROM public.%2$I WHERE %1$I IS NOT NULL
                    GROUP BY 1 HAVING count(*) > 1) d', col, tbl) INTO dupes;
    IF dupes > 0 THEN
      RAISE EXCEPTION '%.% has % duplicated value(s) — resolve them before running this migration.', tbl, col, dupes;
    END IF;

    -- c) Rows that never got an id: give them one (year of their own registration).
    FOR r IN EXECUTE format('SELECT ctid AS row_ref, created_at FROM public.%I WHERE %I IS NULL ORDER BY created_at NULLS FIRST', tbl, col) LOOP
      new_id := issue_account_id(pfx, tbl, r.created_at);
      EXECUTE format('UPDATE public.%I SET %I = $1 WHERE ctid = $2', tbl, col) USING new_id, r.row_ref;
    END LOOP;

    -- d) NOT NULL + UNIQUE (only add a unique index if none exists on exactly this column).
    EXECUTE format('ALTER TABLE public.%I ALTER COLUMN %I SET NOT NULL', tbl, col);
    IF NOT EXISTS (
      SELECT 1 FROM pg_index i
      JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = i.indkey[0]
      WHERE i.indrelid = ('public.' || tbl)::regclass AND i.indisunique AND i.indnkeyatts = 1
        AND a.attname = col AND i.indpred IS NULL
    ) THEN
      EXECUTE format('CREATE UNIQUE INDEX %I ON public.%I (%I)', tbl || '_' || col || '_uniq', tbl, col);
    END IF;

    -- e) Triggers. Lab triggers are named lab_<name> so a re-run of lab-admin-schema.sql
    --    (which copies triggers as lab_<name>) sees them and does not add duplicates.
    EXECUTE format('DROP TRIGGER IF EXISTS %I ON public.%I', trg_prefix || 'assign_account_id', tbl);
    EXECUTE format('CREATE TRIGGER %I BEFORE INSERT ON public.%I FOR EACH ROW EXECUTE FUNCTION assign_account_id(%L, %L)',
                   trg_prefix || 'assign_account_id', tbl, col, pfx);
    EXECUTE format('DROP TRIGGER IF EXISTS %I ON public.%I', trg_prefix || 'keep_account_id', tbl);
    EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OF %I ON public.%I FOR EACH ROW EXECUTE FUNCTION keep_account_id(%L)',
                   trg_prefix || 'keep_account_id', col, tbl, col);
  END LOOP;

  -- f) Legacy vendor ids that survive only as references (their vendor row was deleted):
  --    reserve them too, so they are never handed to a new vendor.
  FOR r IN
    SELECT c.table_name AS tbl FROM information_schema.columns c
    WHERE c.table_schema = 'public' AND c.column_name = 'vendor_id' AND c.data_type = 'text'
      AND c.table_name IN ('activation_keys','lab_activation_keys','payments','lab_payments',
                           'device_status','lab_device_status','device_timeline','lab_device_timeline')
  LOOP
    EXECUTE format(
      'INSERT INTO public_id_registry (public_id, scope, source)
       SELECT DISTINCT vendor_id, ''VND'', %1$L FROM public.%1$I WHERE vendor_id LIKE ''VND-%%''
       ON CONFLICT (public_id) DO NOTHING', r.tbl);
  END LOOP;
END $$;

-- ── 4. Diagnostics: BUG / CR codes + environment ───────────────────────────
ALTER TABLE diag_issues  ADD COLUMN IF NOT EXISTS environment text NOT NULL DEFAULT 'production';
ALTER TABLE diag_crashes ADD COLUMN IF NOT EXISTS environment text NOT NULL DEFAULT 'production';
ALTER TABLE ops_incidents ADD COLUMN IF NOT EXISTS environment text NOT NULL DEFAULT 'production';
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['diag_issues','diag_crashes','ops_incidents'] LOOP
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = t || '_environment_check') THEN
      EXECUTE format('ALTER TABLE %I ADD CONSTRAINT %I CHECK (environment IN (''production'',''test''))', t, t || '_environment_check');
    END IF;
  END LOOP;
END $$;

-- Legacy codes (BUG-00058, CR-20261015-B2EB6, INC-20261015-0001) are kept as they are; their
-- shapes differ from the new ones, so they can never collide. `code` stays UNIQUE.
ALTER TABLE diag_issues  ALTER COLUMN code DROP DEFAULT;   -- was 'BUG-' || diag_issue_seq
ALTER TABLE ops_incidents ALTER COLUMN code DROP DEFAULT;  -- was 'INC-YYYYMMDD-' || ops_incident_seq

CREATE OR REPLACE FUNCTION assign_record_code()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_period text; v_prefix text := TG_ARGV[0];
BEGIN
  IF v_prefix = 'CR' THEN
    v_period := to_char(coalesce(NEW.ts, now()) AT TIME ZONE 'UTC', 'YYYYMMDD');      -- crash event day
  ELSIF v_prefix = 'INC' THEN
    v_period := to_char(coalesce(NEW.started_at, now()) AT TIME ZONE 'UTC', 'YYYY');
  ELSE
    v_period := to_char(now() AT TIME ZONE 'UTC', 'YYYY');
  END IF;
  -- Always generated here; a client-supplied code is ignored.
  NEW.code := v_prefix || '-' || v_period || '-' || public_id_pad(next_public_seq(v_prefix, v_period));
  RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION keep_record_code()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.code IS DISTINCT FROM OLD.code THEN
    RAISE EXCEPTION 'code is permanent and cannot be changed' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS assign_record_code ON diag_issues;
CREATE TRIGGER assign_record_code BEFORE INSERT ON diag_issues FOR EACH ROW EXECUTE FUNCTION assign_record_code('BUG');
DROP TRIGGER IF EXISTS assign_record_code ON diag_crashes;
CREATE TRIGGER assign_record_code BEFORE INSERT ON diag_crashes FOR EACH ROW EXECUTE FUNCTION assign_record_code('CR');
DROP TRIGGER IF EXISTS assign_record_code ON ops_incidents;
CREATE TRIGGER assign_record_code BEFORE INSERT ON ops_incidents FOR EACH ROW EXECUTE FUNCTION assign_record_code('INC');

DROP TRIGGER IF EXISTS keep_record_code ON diag_issues;
CREATE TRIGGER keep_record_code BEFORE UPDATE OF code ON diag_issues FOR EACH ROW EXECUTE FUNCTION keep_record_code();
DROP TRIGGER IF EXISTS keep_record_code ON diag_crashes;
CREATE TRIGGER keep_record_code BEFORE UPDATE OF code ON diag_crashes FOR EACH ROW EXECUTE FUNCTION keep_record_code();
DROP TRIGGER IF EXISTS keep_record_code ON ops_incidents;
CREATE TRIGGER keep_record_code BEFORE UPDATE OF code ON ops_incidents FOR EACH ROW EXECUTE FUNCTION keep_record_code();

-- diag_touch_issue, rewritten so a RECURRING fingerprint never fires the insert trigger (an
-- INSERT … ON CONFLICT runs BEFORE INSERT triggers even when it ends up updating, which would
-- burn a BUG number on every repeat). Existing issue → plain UPDATE; new → INSERT.
-- Adds p_environment: an issue is 'test' until it is seen once in production.
DROP FUNCTION IF EXISTS diag_touch_issue(text, text, text, text, text, text, text, text, text,
  text, text, text, text, text, text, int, timestamptz);
CREATE OR REPLACE FUNCTION diag_touch_issue(
  p_panel text, p_fingerprint text, p_kind text, p_severity text, p_title text,
  p_product text, p_exc_type text, p_message text, p_stack text,
  p_expected text, p_actual text,
  p_school text, p_machine text, p_version text, p_module text,
  p_count int, p_seen timestamptz, p_environment text DEFAULT 'production'
) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_id  uuid;
  v_env text := CASE WHEN p_environment = 'test' THEN 'test' ELSE 'production' END;
BEGIN
  SELECT id INTO v_id FROM diag_issues WHERE panel = p_panel AND fingerprint = p_fingerprint;
  IF v_id IS NULL THEN
    INSERT INTO diag_issues (panel, fingerprint, kind, severity, title, product_id, exception_type,
      message_sample, stack_sample, expected_behavior, actual_behavior, occurrence_count,
      affected_schools, affected_machines, affected_versions, affected_modules, first_seen_at, last_seen_at, environment)
    VALUES (p_panel, p_fingerprint, p_kind, p_severity, p_title, p_product, p_exc_type, p_message, p_stack,
      p_expected, p_actual, p_count,
      array_remove(array[p_school], null), array_remove(array[p_machine], null),
      array_remove(array[p_version], null), array_remove(array[p_module], null), p_seen, p_seen, v_env)
    ON CONFLICT (panel, fingerprint) DO NOTHING
    RETURNING id INTO v_id;
    IF v_id IS NOT NULL THEN RETURN v_id; END IF;
    -- Lost a race with a concurrent insert of the same fingerprint → update that row.
    SELECT id INTO v_id FROM diag_issues WHERE panel = p_panel AND fingerprint = p_fingerprint;
  END IF;

  UPDATE diag_issues AS i SET
    occurrence_count = i.occurrence_count + p_count,
    last_seen_at = greatest(i.last_seen_at, p_seen),
    severity = CASE WHEN p_kind = 'CRASH' THEN p_severity ELSE i.severity END,
    kind = CASE WHEN p_kind = 'CRASH' THEN 'CRASH' ELSE i.kind END,
    stack_sample = coalesce(i.stack_sample, p_stack),
    message_sample = coalesce(i.message_sample, p_message),
    affected_schools = CASE WHEN p_school IS NULL OR p_school = any(i.affected_schools)
      OR cardinality(i.affected_schools) >= 500 THEN i.affected_schools ELSE i.affected_schools || p_school END,
    affected_machines = CASE WHEN p_machine IS NULL OR p_machine = any(i.affected_machines)
      OR cardinality(i.affected_machines) >= 500 THEN i.affected_machines ELSE i.affected_machines || p_machine END,
    affected_versions = CASE WHEN p_version IS NULL OR p_version = any(i.affected_versions)
      OR cardinality(i.affected_versions) >= 200 THEN i.affected_versions ELSE i.affected_versions || p_version END,
    affected_modules = CASE WHEN p_module IS NULL OR p_module = any(i.affected_modules)
      OR cardinality(i.affected_modules) >= 200 THEN i.affected_modules ELSE i.affected_modules || p_module END,
    status = CASE WHEN i.status IN ('RESOLVED','DELETE_PENDING','DELETED') THEN 'REOPENED' ELSE i.status END,
    reopen_count = i.reopen_count + CASE WHEN i.status IN ('RESOLVED','DELETE_PENDING','DELETED') THEN 1 ELSE 0 END,
    delete_after = CASE WHEN i.status IN ('RESOLVED','DELETE_PENDING','DELETED') THEN NULL ELSE i.delete_after END,
    deleted_at = CASE WHEN i.status IN ('RESOLVED','DELETE_PENDING','DELETED') THEN NULL ELSE i.deleted_at END,
    environment = CASE WHEN v_env = 'production' THEN 'production' ELSE i.environment END
  WHERE i.id = v_id;
  RETURN v_id;
END $$;

REVOKE ALL ON FUNCTION diag_touch_issue(text, text, text, text, text, text, text, text, text,
  text, text, text, text, text, text, int, timestamptz, text) FROM public, anon, authenticated;
REVOKE ALL ON FUNCTION next_public_seq(text, text) FROM public, anon, authenticated;
REVOKE ALL ON FUNCTION issue_account_id(text, text, timestamptz) FROM public, anon, authenticated;


-- ── Checks ─────────────────────────────────────────────────────────────────
-- Triggers installed (expect 6 assign + 6 keep on accounts, 3 + 3 on bug/crash/incident):
SELECT event_object_table AS tbl, trigger_name
FROM information_schema.triggers
WHERE trigger_name ~ '(assign|keep)_(account_id|record_code)$'
GROUP BY 1, 2 ORDER BY 1, 2;
-- Legacy ids reserved per type:
SELECT scope, count(*) AS reserved FROM public_id_registry GROUP BY scope ORDER BY scope;
